def compute(vars):
    operating_leases = vars["v1"]
    total_contractual_obligations = vars["v2"]

    if total_contractual_obligations == 0:
        return None

    value = (operating_leases / total_contractual_obligations) * 100

    return {
        "value": value,
        "trace": {
            "operating_leases": operating_leases,
            "total_contractual_obligations": total_contractual_obligations,
            "ratio": operating_leases / total_contractual_obligations,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
